def binary_argv(binary, run, models_dir, counts_only=False, heap_cap=None):
    argv = [binary, '--case', run['model'], '--heap-cap-bytes', str(heap_cap or run['heap_cap_bytes'])]
    path = model_file(models_dir, run['model'], run['members'])
    if path:
        argv += ['--model-file', path]
    if counts_only:
        argv.append('--counts-only')
    return argv


def objects_of(record_dir, run_id):
    path = os.path.join(record_dir, run_id + '.jsonl')
    if not os.path.exists(path):
        return []
    with open(path) as fh:
        return k6.jsonl(fh)


def by_kind(objects, kind):
    return next((o for o in objects if o.get('kind') == kind), None)


def reclassify(record, record_dir):
    """K6's `classify` knows K6's own heap-cap marker. V-K's allocator writes its own."""
    path = os.path.join(record_dir, record['run_id'] + '.stderr.txt')
    if record['classification'] == 'error' and os.path.exists(path):
        with open(path) as fh:
            if VK_HEAP_CAP_MARKER in fh.read():
                record = dict(record, classification='heap_cap_abort', classification_detail='vk_scale marker')
    return record


# --------------------------------------------------------------- counts


def run_counts(binary, models_dir, out_path, tiers=None, log=print):
    """Counts-only runs (no solve), one process per model, under a 512 MiB heap cap."""
    record_dir = os.path.join(os.path.dirname(os.path.abspath(out_path)), 'counts_runs')
    lines = []
    for run in [r for r in schedule() if tiers is None or r['tier'] in tiers]:
        rec = k6.launch(binary_argv(binary, run, models_dir, counts_only=True, heap_cap=COUNTS_CAP_BYTES),
                        rss_cap_bytes=k6.C_DEFAULT, timeout_s=600, record_dir=record_dir,
                        run_id='counts_' + run['model'])
        objects = objects_of(record_dir, 'counts_' + run['model'])
        counts = by_kind(objects, 'counts')
        line = {'kind': 'counts', 'model': run['model'], 'members': run['members'],
                'classification': rec['classification'], 'wall_s': rec['wall_s'],
                'heap_peak': (by_kind(objects, 'summary') or {}).get('repeats_heap_peak')}
        if counts:
            line.update({k: v for k, v in counts.items() if k not in ('kind', 'schema')})
            line[k6.estimate_key(MODE)] = counts['estimate_max_bytes']
        lines.append(line)
        log('%s: %s estimate %s B' % (run['model'], rec['classification'], line.get('estimate_max_bytes')))
    with open(out_path, 'w') as fh:
        for line in lines:
            fh.write(json.dumps(line, sort_keys=True) + '\n')
    return lines


# --------------------------------------------------------------- admission


def admission(run, counts, records, baseline_rss, baseline_footprint, approve_10000):
//! K6b's adapter: a K6 kernel model as K4's `SourceParts` (T3 K6b plan §3.2).
//!
//! - Nodes in the model's order (R1's order for RF-LARGE); node k is node k.
//! - Member k (0-based, in the model's order) has id k + 1, R1's 1-based member
//!   number, with the model's section and `y_reference` (P1's rule for
//!   RF-LARGE, ROOT's K6 ruling N4).
//! - Every restrained DOF is a constraint at 0.0.
//! - One nodal load per nonzero (DOF, value), with source id `k6:<global DOF>`.
//! - One station per member at fraction 0.5 (id = the member id), as K4's own
//!   adapter has, for R1's mid-span bending rows.
//! - No springs, directional springs or support groups: RF-LARGE and the
//!   DEC-053 nine have none.
//!
//! `K6Model` holds exact binary64 values already, so nothing is rounded here.

use super::super::models::K6Model;
use open_pipe_stress_frame_kernel::structural::retained_api::{
    Constraint, Dof, NodalLoad, PrimitiveSource, SourceError, SourceParts, Station, StraightMember,
};

/// The fraction of every member's station.
pub const STATION_FRACTION: f64 = 0.5;

/// The ledger source id of the load at a global DOF.
pub fn load_source_id(global_dof: usize) -> String {
    format!("k6:{global_dof}")
}

/// A member's K4 id: its 1-based position in the model's member order.
pub fn member_id(index: usize) -> u32 {
    u32::try_from(index + 1).expect("fewer than 2^32 members")
}

fn dof(global: usize) -> Dof {
    Dof::from_global(global)
}

/// The model's source parts (module documentation).
pub fn source_parts(model: &K6Model) -> SourceParts {
    let s = &model.section;
    let node = |i: usize| u32::try_from(i).expect("fewer than 2^32 nodes");
    SourceParts {
        nodes: model.nodes.iter().map(|(_, p)| *p).collect(),
        members: model
            .members
            .iter()
            .enumerate()
            .map(|(k, (_, i, j, y))| StraightMember {
                id: member_id(k),
                node_i: node(*i),
                node_j: node(*j),
                elastic_modulus: s.elastic_modulus,
                shear_modulus: s.shear_modulus,
                area: s.area,
                second_moment_y: s.second_moment_y,
                second_moment_z: s.second_moment_z,
                torsion_constant: s.torsion_constant,
                y_reference: *y,
            })
            .collect(),
        constraints: model
            .restrained_dofs()
            .into_iter()
            .map(|g| Constraint {
                dof: dof(g),
                value: 0.0,
            })
            .collect(),
        loads: model
            .loads
            .iter()
            .map(|&(g, value)| NodalLoad {
                dof: dof(g),
                value,
                source_id: load_source_id(g),
            })
            .collect(),
        stations: (0..model.member_count())
            .map(|k| Station {
                id: member_id(k),
                member: member_id(k),
                fraction: STATION_FRACTION,
            })
            .collect(),
        ..SourceParts::default()
    }
}

/// The model's `PrimitiveSource`, or K4's validation refusal.
pub fn source(model: &K6Model) -> Result<PrimitiveSource, SourceError> {
    PrimitiveSource::new(source_parts(model))
}
